package de.corporate.lc.messaging.service;import org.slf4j.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;import org.springframework.stereotype.Component;@Component @ConditionalOnMissingBean(MessagePublisher.class)public class LogMessagePublisher implements MessagePublisher{private static final Logger log=LoggerFactory.getLogger(LogMessagePublisher.class);public void publish(String topic,String key,String payload){log.info("Integration event published locally: topic={}, key={}",topic,key);}public String provider(){return"log";}}
